<template><section><div class="mb-6"><h1 class="text-2xl font-bold">{{t('logs.title')}}</h1></div><div class="card"><div class="mb-4 flex flex-wrap gap-2"><button v-for="x in types" :key="x" class="btn-ghost" :class="type===x?'!bg-brand-500/15 !text-brand-300':''" @click="type=x;load()">{{t('logs.'+x)}}</button><input v-model="search" @keyup.enter="load" class="input ms-auto max-w-xs" :placeholder="t('logs.search')"/><button class="btn-ghost" @click="exportLogs">{{t('common.export')}}</button></div><div class="overflow-x-auto"><table class="w-full text-xs"><thead class="text-slate-500"><tr><th class="p-3 text-start">Time</th><th class="p-3 text-start">Actor</th><th class="p-3 text-start">Event</th><th class="p-3 text-start">Details</th><th class="p-3 text-start">IP</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" class="border-t border-white/5"><td class="p-3 whitespace-nowrap">{{new Date(r.created_at||r.logged_at).toLocaleString()}}</td><td class="p-3">{{r.username||r.email||'—'}}</td><td class="p-3">{{r.action||r.event||type}}</td><td class="max-w-xl p-3 font-mono text-slate-500">{{r.details||JSON.stringify({upload:r.upload_bytes,download:r.download_bytes})}}</td><td class="p-3 text-slate-500">{{r.ip||'—'}}</td></tr></tbody></table><div v-if="!rows.length" class="p-10 text-center text-slate-600">{{t('common.noData')}}</div></div></div></section></template>
<script setup lang="ts">import{ref,watch}from'vue';import{useI18n}from'vue-i18n';import{api}from'../api/client';import{useAuthStore}from'../stores/auth';const{t}=useI18n(),types=['audit','login','security','traffic'],type=ref('audit'),search=ref(''),rows=ref<any[]>([]);async function exportLogs(){const res=await fetch(`/api/logs/export?type=${type.value}&search=${encodeURIComponent(search.value)}`,{headers:{Authorization:`Bearer ${useAuthStore().token}`}});const blob=await res.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`3xui-${type.value}-logs.csv`;a.click();URL.revokeObjectURL(a.href)}async function load(){rows.value=(await api.get<any>(`/logs?type=${type.value}&search=${encodeURIComponent(search.value)}`)).rows||[]}watch(type,load);load();</script>
